package com.clara.adapter.rest;
import com.clara.kernel.ClaraException;import com.clara.workspace.application.*;
public final class WorkspaceRunController {private final WorkspaceBusinessRunner runner;public WorkspaceRunController(WorkspaceBusinessRunner runner){if(runner==null)throw new IllegalArgumentException();this.runner=runner;}public RestResponse<WorkspaceRunResult> run(WorkspaceRunRequest request){try{WorkspaceRunResult value=runner.run(request);return RestResponse.ok(value.getStatus()==WorkspaceRunStatus.WAITING_INPUT?202:200,value);}catch(ClaraException e){return RestResponse.error(RestErrors.status(e.getError()),e.getError());}}public RestResponse<WorkspaceRunResult> resume(WorkspaceResumeRequest request){try{WorkspaceRunResult value=runner.resume(request);return RestResponse.ok(value.getStatus()==WorkspaceRunStatus.WAITING_INPUT?202:200,value);}catch(ClaraException e){return RestResponse.error(RestErrors.status(e.getError()),e.getError());}}public RestResponse<Void> cancel(String tenant,String run,String reason){try{runner.cancel(tenant,run,reason);return RestResponse.ok(204,null);}catch(ClaraException e){return RestResponse.error(RestErrors.status(e.getError()),e.getError());}}}
